window.AgentBlazor = window.AgentBlazor || {
  version: "0.1.0-phase1",
  isLoaded: true,
  chat: {
    scrollToBottom: function (elementId) {
      var el = document.getElementById(elementId);
      if (el && typeof el.scrollTo === 'function') {
        el.scrollTo({ top: el.scrollHeight, behavior: 'smooth' });
      }
    },
    attachEnterSubmit: function (textareaId, submitButtonId) {
      if (!textareaId || !submitButtonId) return;
      var textarea = document.getElementById(textareaId);
      var submitBtn = document.getElementById(submitButtonId);
      if (!textarea || !submitBtn) return;
      var handler = function (e) {
        if ((e.key === 'Enter' || e.key === 'NumpadEnter') && !e.shiftKey) {
          e.preventDefault();
          submitBtn.click();
        }
      };
      textarea.addEventListener('keydown', handler);
      textarea._abChatEnterHandler = handler;
    },
    detachEnterSubmit: function (textareaId) {
      var textarea = document.getElementById(textareaId);
      if (textarea && textarea._abChatEnterHandler) {
        textarea.removeEventListener('keydown', textarea._abChatEnterHandler);
        textarea._abChatEnterHandler = null;
      }
    }
  },
  internal: {
    _frontendActions: {},
    _sharedState: {},
    _eventListeners: {},
    _suggestions: [],
    
    capturePageStructure: function () {
      var components = [];
      var knownComponents = ['agent-datagrid', 'agent-dialog', 'agent-form', 'agent-tabs', 'agent-nav-menu', 'agent-select'];
      var knownPrefixes = ['agentdatagrid', 'agentdialog', 'agentform', 'agenttabs', 'agentnavmenu', 'agentselect'];
      
      function getComponentInfo(el) {
        var id = el.id || '';
        var classes = el.className || '';
        var dataAttrs = {};
        
        for (var i = 0; i < el.attributes.length; i++) {
          var attr = el.attributes[i];
          if (attr.name.startsWith('data-ab-')) {
            dataAttrs[attr.name] = attr.value;
          }
        }
        
        var type = '';
        for (var j = 0; j < knownPrefixes.length; j++) {
          if (id.toLowerCase().startsWith(knownPrefixes[j]) || (typeof classes === 'string' && classes.toLowerCase().includes(knownPrefixes[j]))) {
            type = knownComponents[j].replace('agent-', '').replace('-', '');
            break;
          }
        }
        
        if (!type && el.tagName) {
          type = el.tagName.toLowerCase();
        }
        
        return {
          id: id,
          type: type,
          tagName: el.tagName ? el.tagName.toLowerCase() : '',
          classes: typeof classes === 'string' ? classes.split(' ').filter(function(c) { return c; }) : [],
          dataAttributes: dataAttrs,
          childCount: el.children ? el.children.length : 0
        };
      }
      
      function walkTree(el, depth) {
        if (depth > 10) return;
        
        var info = getComponentInfo(el);
        if (info.type && info.type !== el.tagName) {
          components.push(info);
        }
        
        if (el.children) {
          for (var i = 0; i < el.children.length; i++) {
            walkTree(el.children[i], depth + 1);
          }
        }
      }
      
      walkTree(document.body, 0);
      
      return {
        url: window.location.pathname,
        timestamp: new Date().toISOString(),
        components: components
      };
    },
    
    registerFrontendAction: function (name, handler) {
      this._frontendActions[name] = handler;
    },
    
    unregisterFrontendAction: function (name) {
      delete this._frontendActions[name];
    },
    
    executeFrontendAction: function (name, args) {
      var action = this._frontendActions[name];
      if (typeof action === 'function') {
        try {
          var result = action(args);
          return { success: true, result: result };
        } catch (e) {
          return { success: false, error: e.message };
        }
      }
      return { success: false, error: 'Action not found: ' + name };
    },
    
    getFrontendActions: function () {
      return Object.keys(this._frontendActions);
    },
    
    setSharedState: function (key, value) {
      this._sharedState[key] = value;
      this._emit('stateChanged', { key: key, value: value });
    },
    
    getSharedState: function (key) {
      return key ? this._sharedState[key] : this._sharedState;
    },
    
    getAllSharedState: function () {
      return JSON.parse(JSON.stringify(this._sharedState));
    },
    
    clearSharedState: function () {
      this._sharedState = {};
      this._emit('stateChanged', { key: null, value: null });
    },
    
    addEventListener: function (event, callback) {
      if (!this._eventListeners[event]) {
        this._eventListeners[event] = [];
      }
      this._eventListeners[event].push(callback);
    },
    
    removeEventListener: function (event, callback) {
      if (this._eventListeners[event]) {
        var idx = this._eventListeners[event].indexOf(callback);
        if (idx > -1) {
          this._eventListeners[event].splice(idx, 1);
        }
      }
    },
    
    _emit: function (event, data) {
      if (this._eventListeners[event]) {
        this._eventListeners[event].forEach(function(cb) {
          try { cb(data); } catch (e) {}
        });
      }
    },
    
    emitAgentEvent: function (eventType, data) {
      this._emit('agent:' + eventType, data);
    },
    
    setSuggestions: function (suggestions) {
      this._suggestions = suggestions || [];
      this._emit('suggestionsChanged', this._suggestions);
    },
    
    getSuggestions: function () {
      return this._suggestions.slice();
    },
    
    clearSuggestions: function () {
      this._suggestions = [];
      this._emit('suggestionsChanged', []);
    },
    
    getViewportInfo: function () {
      return {
        width: window.innerWidth,
        height: window.innerHeight,
        scrollX: window.scrollX,
        scrollY: window.scrollY,
        devicePixelRatio: window.devicePixelRatio
      };
    },
    
    getActiveElement: function () {
      var el = document.activeElement;
      if (!el) return null;
      return {
        tagName: el.tagName,
        id: el.id,
        className: el.className,
        value: el.value,
        type: el.type
      };
    }
  }
};
